-- 02020: Commerce Pro license product copy, EN + FR (vendor-only rows: nextblock.dev has them,
-- fresh installs do not, so this is a no-op everywhere else). Copy only; no schema.
--
-- The page claimed things the code does not do:
-- * "real-time exchange rates" -- rates are ECB reference rates from api.frankfurter.dev, refreshed
--   at most once a day from the CMS layout via after() (apps/nextblock/lib/commerce/currency-rates-refresh.ts),
--   with a "Sync Live Rates" button and the optional /api/cron/sync-currencies route. The Vercel cron
--   that used to run this was dropped because vercel.json ships to every 1-click install.
-- * "< 50ms Cart API Response" -- there is no cart API route at all.
-- * "135+ Currencies Supported" / "40+ Tax Jurisdictions" -- currencies are rows an operator creates,
--   and tax coverage is Stripe's, not ours.
-- * "Every API path is edge-cached" -- public pages come from the 5-minute content cache that clears
--   on publish; HTML is served must-revalidate.
-- * "optimistic locking" -- stock is deducted under SELECT ... FOR UPDATE (libs/ecommerce order-inventory.ts).
-- * "email notifications" -- no order email exists; orders produce printable invoices.
-- * "shares inventory and pricing" -- stock is shared through the SKU, prices are per language row.
-- The page also never mentioned the 30-day free trial, the French buttons pointed at the English
-- product, the cards skipped from h3 to h5, and neither language had SEO meta (45/100 in the audit;
-- the new copy scores 85). Same copy as apps/nextblock/app/api/cron/reset-sandbox/commerce-product-copy.ts,
-- which re-seeds the sandbox after every reset.
--
-- Guarded: each product is replaced only while it still carries the shipped signature, so a product
-- the vendor rewrote by hand is left alone (a NOTICE names it). Idempotent: the new signature stops
-- a second run.
--
-- NOTE: keep the word "sandbox" OUT of this filename -- generate-sandbox-reset.ts excludes any
-- migration whose filename contains "sandbox" from the reset bundle.

DO $nb_02020_products$
DECLARE
  v_id uuid;
  v_lang bigint;
BEGIN

  -- English
  v_id := NULL;
  SELECT p.id, p.language_id INTO v_id, v_lang
    FROM public.products AS p JOIN public.languages AS l ON l.id = p.language_id
   WHERE p.slug = 'nextblock-commerce-pro-commerce-license' AND l.code = 'en'
   ORDER BY p.id LIMIT 1;
  IF v_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.blocks WHERE product_id = v_id AND content::text LIKE $t$%Enterprise E-Commerce Engine%$t$)
       AND NOT EXISTS (SELECT 1 FROM public.blocks WHERE product_id = v_id AND content::text LIKE $t$%Days free, no card%$t$) THEN
      DELETE FROM public.blocks WHERE product_id = v_id;
      INSERT INTO public.blocks (product_id, language_id, block_type, content, "order") VALUES
        (v_id, v_lang, 'section', $nbcm0en${"padding":{"top":"xl","bottom":"xl"},"background":{"type":"gradient","gradient":{"type":"linear","stops":[{"color":"#022c22","position":0},{"color":"#064e3b","position":40},{"color":"#0f172a","position":100}],"direction":"135deg"}},"column_gap":"xl","column_blocks":[[{"content":{"html_content":"<p class=\"text-xs uppercase tracking-[0.3em] text-emerald-400 font-semibold mb-4\">Enterprise E-Commerce Engine</p>\n<h2 class=\"text-3xl md:text-5xl font-extrabold text-white leading-tight mb-5\">Turn Next.js Into a<br/>Global Storefront.</h2>\n<p class=\"text-base md:text-lg text-slate-200 leading-relaxed mb-6\">Commerce Pro is a composable, developer-first engine that powers physical product catalogs, digital licensing, and subscription commerce — all from your existing Next.js stack. Try it free for 30 days, no credit card.</p>"},"block_type":"text"},{"content":{"url":"https://nextblock.dev/product/nextblock-commerce-pro-commerce-license","size":"lg","text":"Get Commerce Pro →","variant":"default","position":"left"},"block_type":"button"}],[{"content":{"html_content":"<div class=\"rounded-2xl border border-emerald-700 bg-slate-950 p-6 shadow-xl sm:p-8\">\n<h3 class=\"text-lg font-bold text-white mb-5\">Why Teams Choose Commerce Pro</h3>\n<ul class=\"space-y-4 text-sm leading-relaxed text-slate-300\">\n  <li class=\"flex items-start gap-3\">\n    <span class=\"flex-shrink-0 w-6 h-6 rounded-full bg-emerald-950 flex items-center justify-center text-emerald-300 text-xs font-bold\">✓</span>\n    <span><strong class=\"text-white\">Multi-Currency Pricing</strong> — daily exchange-rate sync, charm pricing rules, and a currency suggested by the visitor's locale.</span>\n  </li>\n  <li class=\"flex items-start gap-3\">\n    <span class=\"flex-shrink-0 w-6 h-6 rounded-full bg-emerald-950 flex items-center justify-center text-emerald-300 text-xs font-bold\">✓</span>\n    <span><strong class=\"text-white\">Tax Automation</strong> — switch on Stripe Tax and checkout calculates and collects tax for you, with the tax lines stored on every order.</span>\n  </li>\n  <li class=\"flex items-start gap-3\">\n    <span class=\"flex-shrink-0 w-6 h-6 rounded-full bg-emerald-950 flex items-center justify-center text-emerald-300 text-xs font-bold\">✓</span>\n    <span><strong class=\"text-white\">Resilient Stock Tracking</strong> — inventory locks at checkout to prevent over-selling, with per-variant control.</span>\n  </li>\n  <li class=\"flex items-start gap-3\">\n    <span class=\"flex-shrink-0 w-6 h-6 rounded-full bg-emerald-950 flex items-center justify-center text-emerald-300 text-xs font-bold\">✓</span>\n    <span><strong class=\"text-white\">Flexible Shipping Zones</strong> — rate tables, free-shipping thresholds, and per-country rules out of the box.</span>\n  </li>\n</ul>\n</div>"},"block_type":"text"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":1,"desktop":2},"vertical_alignment":"center"}$nbcm0en$::jsonb, 0),
        (v_id, v_lang, 'section', $nbcm1en${"padding":{"top":"lg","bottom":"lg"},"background":{"type":"theme","theme":"muted"},"column_gap":"lg","column_blocks":[[{"content":{"html_content":"<p class=\"text-center\"><span class=\"block text-2xl font-extrabold text-foreground\">30</span><span class=\"text-xs text-muted-foreground uppercase tracking-wider\">Days free, no card</span></p>"},"block_type":"text"}],[{"content":{"html_content":"<p class=\"text-center\"><span class=\"block text-2xl font-extrabold text-foreground\">2</span><span class=\"text-xs text-muted-foreground uppercase tracking-wider\">Checkout providers</span></p>"},"block_type":"text"}],[{"content":{"html_content":"<p class=\"text-center\"><span class=\"block text-2xl font-extrabold text-foreground\">Daily</span><span class=\"text-xs text-muted-foreground uppercase tracking-wider\">Exchange-rate sync</span></p>"},"block_type":"text"}],[{"content":{"html_content":"<p class=\"text-center\"><span class=\"block text-2xl font-extrabold text-foreground\">EN + FR</span><span class=\"text-xs text-muted-foreground uppercase tracking-wider\">Linked storefronts</span></p>"},"block_type":"text"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":2,"desktop":4},"vertical_alignment":"center"}$nbcm1en$::jsonb, 1),
        (v_id, v_lang, 'section', $nbcm2en${"padding":{"top":"xl","bottom":"xl"},"background":{"type":"none"},"column_gap":"lg","column_blocks":[[{"content":{"html_content":"<div class=\"h-full rounded-2xl border border-slate-200 bg-white p-6 shadow-sm transition-colors hover:border-emerald-300 hover:bg-slate-50 dark:border-white/10 dark:bg-slate-950 dark:hover:border-emerald-500 sm:p-7\">\n<div class=\"mb-4 inline-flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300\"><svg class=\"h-5 w-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"></rect><path d=\"M3 10h18M7 15h3\"></path></svg></div>\n<h4 class=\"text-base font-bold text-slate-900 dark:text-white mb-2\">Headless Stripe Checkout</h4>\n<p class=\"text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">Integrated checkout session creation for single or multiple items. Auto-fulfillment fires via webhook events, with built-in idempotency guards.</p>\n</div>"},"block_type":"text"}],[{"content":{"html_content":"<div class=\"h-full rounded-2xl border border-slate-200 bg-white p-6 shadow-sm transition-colors hover:border-emerald-300 hover:bg-slate-50 dark:border-white/10 dark:bg-slate-950 dark:hover:border-emerald-500 sm:p-7\">\n<div class=\"mb-4 inline-flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300\"><svg class=\"h-5 w-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M15 7a4 4 0 1 1-2.83 6.83L7 19H4v-3h3l2.17-2.17A4 4 0 0 1 15 7Z\"></path><path d=\"M17.5 8.5h.01\"></path></svg></div>\n<h4 class=\"text-base font-bold text-slate-900 dark:text-white mb-2\">Freemius Digital Licensing</h4>\n<p class=\"text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">Distribute software downloads, validate license keys, and manage SaaS trial periods natively — no third-party integration layer required.</p>\n</div>"},"block_type":"text"}],[{"content":{"html_content":"<div class=\"h-full rounded-2xl border border-slate-200 bg-white p-6 shadow-sm transition-colors hover:border-emerald-300 hover:bg-slate-50 dark:border-white/10 dark:bg-slate-950 dark:hover:border-emerald-500 sm:p-7\">\n<div class=\"mb-4 inline-flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300\"><svg class=\"h-5 w-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"4\" y=\"5\" width=\"16\" height=\"14\" rx=\"2\"></rect><path d=\"m4 15 4-4 4 4 3-3 5 5\"></path><circle cx=\"15\" cy=\"9\" r=\"1\"></circle></svg></div>\n<h4 class=\"text-base font-bold text-slate-900 dark:text-white mb-2\">Visual Merchandising</h4>\n<p class=\"text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">Content creators can add product details pages, highlight promotions, and build full landing pages — all inside the block editor, no code needed.</p>\n</div>"},"block_type":"text"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":2,"desktop":3},"vertical_alignment":"stretch"}$nbcm2en$::jsonb, 2),
        (v_id, v_lang, 'section', $nbcm3en${"padding":{"top":"xl","bottom":"xl"},"background":{"type":"gradient","gradient":{"type":"linear","stops":[{"color":"#020617","position":0},{"color":"#0f172a","position":100}],"direction":"180deg"}},"column_gap":"xl","column_blocks":[[{"content":{"html_content":"<p class=\"text-xs uppercase tracking-[0.3em] text-emerald-400 font-semibold mb-4\">Under The Hood</p>\n<h3 class=\"text-2xl md:text-3xl font-extrabold text-white mb-4\">Built for Production Scale</h3>\n<p class=\"text-slate-300 leading-relaxed mb-5\">Commerce Pro was designed from day one for high-traffic stores. Store pages come from a public content cache that clears the moment you publish, every database query is indexed, and every webhook handler is idempotent.</p>\n<ul class=\"space-y-3 text-sm text-slate-400\">\n  <li class=\"flex items-start gap-2.5\">\n    <span class=\"text-emerald-400\">→</span>\n    <span>Variant-level inventory with row-locked stock deduction</span>\n  </li>\n  <li class=\"flex items-start gap-2.5\">\n    <span class=\"text-emerald-400\">→</span>\n    <span>Automatic shipping zone calculation and rate tables</span>\n  </li>\n  <li class=\"flex items-start gap-2.5\">\n    <span class=\"text-emerald-400\">→</span>\n    <span>Real-time order status with Stripe webhook sync</span>\n  </li>\n  <li class=\"flex items-start gap-2.5\">\n    <span class=\"text-emerald-400\">→</span>\n    <span>Product attributes and filterable facets system</span>\n  </li>\n</ul>"},"block_type":"text"}],[{"content":{"html_content":"<div class=\"space-y-4\">\n<div class=\"p-5 rounded-xl border border-slate-700 bg-slate-900\">\n  <h4 class=\"text-sm font-bold text-white mb-1\">Order Management</h4>\n  <p class=\"text-xs text-slate-400 leading-relaxed\">Full order lifecycle from cart to fulfillment. Automatic status transitions, printable invoices, and refund handling baked in.</p>\n</div>\n<div class=\"p-5 rounded-xl border border-slate-700 bg-slate-900\">\n  <h4 class=\"text-sm font-bold text-white mb-1\">Product Categories</h4>\n  <p class=\"text-xs text-slate-400 leading-relaxed\">Hierarchical taxonomy with slugs, media attachments, and full i18n support. Categories are managed directly in the CMS dashboard.</p>\n</div>\n<div class=\"p-5 rounded-xl border border-slate-700 bg-slate-900\">\n  <h4 class=\"text-sm font-bold text-white mb-1\">Multi-Language Storefronts</h4>\n  <p class=\"text-xs text-slate-400 leading-relaxed\">Products, categories, and checkout flows are fully translatable. Each language variant keeps its own prices and SEO metadata, and shares stock with its twins through the product SKU.</p>\n</div>\n</div>"},"block_type":"text"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":1,"desktop":2},"vertical_alignment":"center"}$nbcm3en$::jsonb, 3),
        (v_id, v_lang, 'section', $nbcm4en${"padding":{"top":"xl","bottom":"xl"},"background":{"type":"gradient","gradient":{"type":"linear","stops":[{"color":"#064e3b","position":0},{"color":"#022c22","position":100}],"direction":"135deg"}},"column_gap":"none","column_blocks":[[{"content":{"level":2,"textAlign":"center","textColor":"background","text_content":"Ready to launch your storefront?"},"block_type":"heading"},{"content":{"html_content":"<p class=\"text-center text-emerald-100 max-w-xl mx-auto mt-2 mb-6\">Start selling today with Commerce Pro. Multi-currency pricing, automatic tax, and shipping zones are ready out of the box, and the first 30 days are free.</p>"},"block_type":"text"},{"content":{"url":"https://nextblock.dev/product/nextblock-commerce-pro-commerce-license","size":"lg","text":"Start the 30-Day Free Trial","variant":"secondary","position":"center"},"block_type":"button"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":1,"desktop":1},"vertical_alignment":"center"}$nbcm4en$::jsonb, 4);
      UPDATE public.products
         SET title = $t$NextBlock™ Commerce Pro - Commerce License$t$,
             short_description = $t$NextBlock™ Commerce Pro turns your CMS into a storefront: products and variants, multi-currency pricing with daily rate sync, automatic tax through Stripe Tax, shipping zones, and checkout with Stripe or Freemius. Free for 30 days, no credit card.$t$,
             meta_title = $t$NextBlock™ Commerce Pro | Next.js Storefront License$t$,
             meta_description = $t$Sell products, licences and subscriptions from your Next.js site: multi-currency pricing, Stripe Tax, shipping zones, Stripe or Freemius checkout.$t$,
             updated_at = now()
       WHERE id = v_id;
    ELSIF NOT EXISTS (SELECT 1 FROM public.blocks WHERE product_id = v_id AND content::text LIKE $t$%Days free, no card%$t$) THEN
      RAISE NOTICE '02020: product nextblock-commerce-pro-commerce-license (en) differs from the shipped copy; left unchanged.';
    END IF;
  END IF;


  -- French
  v_id := NULL;
  SELECT p.id, p.language_id INTO v_id, v_lang
    FROM public.products AS p JOIN public.languages AS l ON l.id = p.language_id
   WHERE p.slug = 'nextblock-commerce-pro-commerce-license-fr' AND l.code = 'fr'
   ORDER BY p.id LIMIT 1;
  IF v_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.blocks WHERE product_id = v_id AND content::text LIKE $t$%Moteur E-Commerce d'Entreprise%$t$)
       AND NOT EXISTS (SELECT 1 FROM public.blocks WHERE product_id = v_id AND content::text LIKE $t$%Jours gratuits, sans carte%$t$) THEN
      DELETE FROM public.blocks WHERE product_id = v_id;
      INSERT INTO public.blocks (product_id, language_id, block_type, content, "order") VALUES
        (v_id, v_lang, 'section', $nbcm0fr${"padding":{"top":"xl","bottom":"xl"},"background":{"type":"gradient","gradient":{"type":"linear","stops":[{"color":"#022c22","position":0},{"color":"#064e3b","position":40},{"color":"#0f172a","position":100}],"direction":"135deg"}},"column_gap":"xl","column_blocks":[[{"content":{"html_content":"<p class=\"text-xs uppercase tracking-[0.3em] text-emerald-400 font-semibold mb-4\">Moteur E-Commerce d'Entreprise</p>\n<h2 class=\"text-3xl md:text-5xl font-extrabold text-white leading-tight mb-5\">Faites de Next.js une<br/>Boutique Mondiale.</h2>\n<p class=\"text-base md:text-lg text-slate-200 leading-relaxed mb-6\">Commerce Pro est un moteur composable pensé pour les développeurs : catalogues physiques, licences numériques et abonnements — le tout depuis votre stack Next.js existant. Essayez-le gratuitement pendant 30 jours, sans carte de crédit.</p>"},"block_type":"text"},{"content":{"url":"https://nextblock.dev/product/nextblock-commerce-pro-commerce-license-fr","size":"lg","text":"Obtenir Commerce Pro →","variant":"default","position":"left"},"block_type":"button"}],[{"content":{"html_content":"<div class=\"rounded-2xl border border-emerald-700 bg-slate-950 p-6 shadow-xl sm:p-8\">\n<h3 class=\"text-lg font-bold text-white mb-5\">Pourquoi choisir Commerce Pro</h3>\n<ul class=\"space-y-4 text-sm leading-relaxed text-slate-300\">\n  <li class=\"flex items-start gap-3\">\n    <span class=\"flex-shrink-0 w-6 h-6 rounded-full bg-emerald-950 flex items-center justify-center text-emerald-300 text-xs font-bold\">✓</span>\n    <span><strong class=\"text-white\">Multi-Devises</strong> — synchronisation quotidienne des taux de change, arrondis personnalisés et devise suggérée selon la langue du visiteur.</span>\n  </li>\n  <li class=\"flex items-start gap-3\">\n    <span class=\"flex-shrink-0 w-6 h-6 rounded-full bg-emerald-950 flex items-center justify-center text-emerald-300 text-xs font-bold\">✓</span>\n    <span><strong class=\"text-white\">Taxes automatisées</strong> — activez Stripe Tax et le paiement calcule et collecte la taxe pour vous, avec le détail conservé sur chaque commande.</span>\n  </li>\n  <li class=\"flex items-start gap-3\">\n    <span class=\"flex-shrink-0 w-6 h-6 rounded-full bg-emerald-950 flex items-center justify-center text-emerald-300 text-xs font-bold\">✓</span>\n    <span><strong class=\"text-white\">Gestion des Stocks</strong> — verrouillage de l'inventaire au checkout pour éviter les surventes, avec contrôle par variante.</span>\n  </li>\n  <li class=\"flex items-start gap-3\">\n    <span class=\"flex-shrink-0 w-6 h-6 rounded-full bg-emerald-950 flex items-center justify-center text-emerald-300 text-xs font-bold\">✓</span>\n    <span><strong class=\"text-white\">Zones d'expédition flexibles</strong> — tables de tarifs, seuils de livraison gratuite et règles par pays inclus.</span>\n  </li>\n</ul>\n</div>"},"block_type":"text"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":1,"desktop":2},"vertical_alignment":"center"}$nbcm0fr$::jsonb, 0),
