        (v_id, v_lang, 'section', $nbcm2fr${"padding":{"top":"xl","bottom":"xl"},"background":{"type":"none"},"column_gap":"lg","column_blocks":[[{"content":{"html_content":"<div class=\"h-full rounded-2xl border border-slate-200 bg-white p-6 shadow-sm transition-colors hover:border-emerald-300 hover:bg-slate-50 dark:border-white/10 dark:bg-slate-950 dark:hover:border-emerald-500 sm:p-7\">\n<div class=\"mb-4 inline-flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300\"><svg class=\"h-5 w-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"></rect><path d=\"M3 10h18M7 15h3\"></path></svg></div>\n<h4 class=\"text-base font-bold text-slate-900 dark:text-white mb-2\">Checkout Stripe Headless</h4>\n<p class=\"text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">Création de sessions Stripe Checkout pour un ou plusieurs articles. Traitement automatique des commandes par webhooks avec protection d'idempotence.</p>\n</div>"},"block_type":"text"}],[{"content":{"html_content":"<div class=\"h-full rounded-2xl border border-slate-200 bg-white p-6 shadow-sm transition-colors hover:border-emerald-300 hover:bg-slate-50 dark:border-white/10 dark:bg-slate-950 dark:hover:border-emerald-500 sm:p-7\">\n<div class=\"mb-4 inline-flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300\"><svg class=\"h-5 w-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M15 7a4 4 0 1 1-2.83 6.83L7 19H4v-3h3l2.17-2.17A4 4 0 0 1 15 7Z\"></path><path d=\"M17.5 8.5h.01\"></path></svg></div>\n<h4 class=\"text-base font-bold text-slate-900 dark:text-white mb-2\">Licences Numériques Freemius</h4>\n<p class=\"text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">Distribuez vos logiciels, validez les clés de licence et gérez les périodes d'essai SaaS — aucune intégration tierce requise.</p>\n</div>"},"block_type":"text"}],[{"content":{"html_content":"<div class=\"h-full rounded-2xl border border-slate-200 bg-white p-6 shadow-sm transition-colors hover:border-emerald-300 hover:bg-slate-50 dark:border-white/10 dark:bg-slate-950 dark:hover:border-emerald-500 sm:p-7\">\n<div class=\"mb-4 inline-flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300\"><svg class=\"h-5 w-5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"4\" y=\"5\" width=\"16\" height=\"14\" rx=\"2\"></rect><path d=\"m4 15 4-4 4 4 3-3 5 5\"></path><circle cx=\"15\" cy=\"9\" r=\"1\"></circle></svg></div>\n<h4 class=\"text-base font-bold text-slate-900 dark:text-white mb-2\">Merchandising Visuel</h4>\n<p class=\"text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">Vos équipes éditoriales enrichissent les fiches produits de landing pages, promotions et galeries — directement dans l'éditeur de blocs.</p>\n</div>"},"block_type":"text"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":2,"desktop":3},"vertical_alignment":"stretch"}$nbcm2fr$::jsonb, 2),
        (v_id, v_lang, 'section', $nbcm3fr${"padding":{"top":"xl","bottom":"xl"},"background":{"type":"gradient","gradient":{"type":"linear","stops":[{"color":"#020617","position":0},{"color":"#0f172a","position":100}],"direction":"180deg"}},"column_gap":"xl","column_blocks":[[{"content":{"html_content":"<p class=\"text-xs uppercase tracking-[0.3em] text-emerald-400 font-semibold mb-4\">Sous le capot</p>\n<h3 class=\"text-2xl md:text-3xl font-extrabold text-white mb-4\">Conçu pour la production à grande échelle</h3>\n<p class=\"text-slate-300 leading-relaxed mb-5\">Commerce Pro a été conçu dès le départ pour les boutiques à fort trafic. Les pages de la boutique proviennent d'un cache de contenu public vidé dès la publication, chaque requête est indexée, et chaque gestionnaire de webhook est idempotent.</p>\n<ul class=\"space-y-3 text-sm text-slate-400\">\n  <li class=\"flex items-start gap-2.5\">\n    <span class=\"text-emerald-400\">→</span>\n    <span>Inventaire par variante avec déduction du stock sous verrou de ligne</span>\n  </li>\n  <li class=\"flex items-start gap-2.5\">\n    <span class=\"text-emerald-400\">→</span>\n    <span>Calcul automatique des zones d'expédition et tables de tarifs</span>\n  </li>\n  <li class=\"flex items-start gap-2.5\">\n    <span class=\"text-emerald-400\">→</span>\n    <span>Statut des commandes en temps réel via synchronisation Stripe webhook</span>\n  </li>\n  <li class=\"flex items-start gap-2.5\">\n    <span class=\"text-emerald-400\">→</span>\n    <span>Système d'attributs produits et de facettes filtrables</span>\n  </li>\n</ul>"},"block_type":"text"}],[{"content":{"html_content":"<div class=\"space-y-4\">\n<div class=\"p-5 rounded-xl border border-slate-700 bg-slate-900\">\n  <h4 class=\"text-sm font-bold text-white mb-1\">Gestion des commandes</h4>\n  <p class=\"text-xs text-slate-400 leading-relaxed\">Cycle de vie complet : du panier à la livraison. Transitions automatiques, factures imprimables et gestion des remboursements intégrées.</p>\n</div>\n<div class=\"p-5 rounded-xl border border-slate-700 bg-slate-900\">\n  <h4 class=\"text-sm font-bold text-white mb-1\">Catégories de produits</h4>\n  <p class=\"text-xs text-slate-400 leading-relaxed\">Taxonomie hiérarchique avec slugs, médias associés et support i18n complet. Les catégories sont gérées directement dans le tableau de bord du CMS.</p>\n</div>\n<div class=\"p-5 rounded-xl border border-slate-700 bg-slate-900\">\n  <h4 class=\"text-sm font-bold text-white mb-1\">Boutiques multilingues</h4>\n  <p class=\"text-xs text-slate-400 leading-relaxed\">Produits, catégories et flux de paiement entièrement traduisibles. Chaque variante linguistique garde ses propres prix et métadonnées SEO, et partage le stock avec ses jumelles grâce au SKU du produit.</p>\n</div>\n</div>"},"block_type":"text"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":1,"desktop":2},"vertical_alignment":"center"}$nbcm3fr$::jsonb, 3),
        (v_id, v_lang, 'section', $nbcm4fr${"padding":{"top":"xl","bottom":"xl"},"background":{"type":"gradient","gradient":{"type":"linear","stops":[{"color":"#064e3b","position":0},{"color":"#022c22","position":100}],"direction":"135deg"}},"column_gap":"none","column_blocks":[[{"content":{"level":2,"textAlign":"center","textColor":"background","text_content":"Prêt à lancer votre boutique ?"},"block_type":"heading"},{"content":{"html_content":"<p class=\"text-center text-emerald-100 max-w-xl mx-auto mt-2 mb-6\">Commencez à vendre dès aujourd'hui avec Commerce Pro. Prix multi-devises, taxes automatiques et zones de livraison sont prêts dès l'installation, et les 30 premiers jours sont gratuits.</p>"},"block_type":"text"},{"content":{"url":"https://nextblock.dev/product/nextblock-commerce-pro-commerce-license-fr","size":"lg","text":"Commencer l'essai gratuit de 30 jours","variant":"secondary","position":"center"},"block_type":"button"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":1,"desktop":1},"vertical_alignment":"center"}$nbcm4fr$::jsonb, 4);
      UPDATE public.products
         SET title = $t$Licence NextBlock™ Commerce Pro$t$,
             short_description = $t$NextBlock™ Commerce Pro transforme votre CMS en boutique : produits et variantes, prix multi-devises avec synchronisation quotidienne des taux, taxes automatiques via Stripe Tax, zones de livraison et paiement Stripe ou Freemius. Gratuit pendant 30 jours, sans carte de crédit.$t$,
             meta_title = $t$NextBlock™ Commerce Pro | Licence boutique Next.js$t$,
             meta_description = $t$Vendez produits, licences et abonnements depuis votre site Next.js : prix multi-devises, Stripe Tax, zones de livraison, paiement Stripe ou Freemius.$t$,
             updated_at = now()
       WHERE id = v_id;
    ELSIF NOT EXISTS (SELECT 1 FROM public.blocks WHERE product_id = v_id AND content::text LIKE $t$%Jours gratuits, sans carte%$t$) THEN
      RAISE NOTICE '02020: product nextblock-commerce-pro-commerce-license-fr (fr) differs from the shipped copy; left unchanged.';
    END IF;
  END IF;

END
$nb_02020_products$;
